import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Science User Group - March 2025","description":"","frontmatter":{"title":"Ceph Science User Group - March 2025","date":"2025-07-29T00:00:00.000Z","updated":"2025-07-30T00:00:00.000Z","tags":["CephFS","调优","分布式存储","Ceph","开源"],"categories":["会议纪要","技术分享"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Science_User_Group_-_March_2025.md","filePath":"posts/2025/Ceph_Science_User_Group_-_March_2025.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Ceph_Science_User_Group_-_March_2025.md"};function o(n,a,s,h,c,p){return i(),t("div",null,[...a[0]||(a[0]=[l('<p>Ceph 科学用户组会议于 2025 年 3 月举行，会议主要围绕 Ceph 使用经验分享、新功能测试和升级流程讨论展开。以下是会议的主要内容和关键讨论点：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><ul><li><strong>主持人</strong>: Enrio (CERN)</li><li><strong>主要演讲人</strong>: Matia (苏黎世科学IT服务)</li><li><strong>会议类型</strong>: 双月会议 (bimonthly meeting)</li><li><strong>参会人员</strong>: Ceph 运维人员、专家、研究人员（来自开放科学实验室、大型研究中心和大学）</li><li><strong>会议目的</strong>: 分享 Ceph 使用经验、测试新功能、升级流程讨论等技术交流</li></ul><h3 id="主要演讲内容-cephfs-调优经验分享-matia" tabindex="-1">主要演讲内容 - CephFS 调优经验分享 (Matia) <a class="header-anchor" href="#主要演讲内容-cephfs-调优经验分享-matia" aria-label="Permalink to &quot;主要演讲内容 - CephFS 调优经验分享 (Matia)&quot;">​</a></h3><p>Matia 分享了他们使用 CephFS 作为可信研究环境 (TRE) 后端存储的经验，包括系统概况、初始配置、生产环境挑战与调优以及经验教训与改进方向。</p><h4 id="系统概况" tabindex="-1">系统概况 <a class="header-anchor" href="#系统概况" aria-label="Permalink to &quot;系统概况&quot;">​</a></h4><ul><li>使用场景：可信研究环境 (TRE) 后端存储</li><li>规模：500 名研究人员，3.2PB 数据</li><li>选择 Ceph 原因：可扩展性和分布式文件系统特性</li></ul><h4 id="初始配置" tabindex="-1">初始配置 <a class="header-anchor" href="#初始配置" aria-label="Permalink to &quot;初始配置&quot;">​</a></h4><ul><li>硬件配置：独立 WAL + DB 设计，置于快速设备上；元数据池位于快速设备；文件系统根目录位于基于机械硬盘的复制池</li></ul><h4 id="生产环境挑战与调优" tabindex="-1">生产环境挑战与调优 <a class="header-anchor" href="#生产环境挑战与调优" aria-label="Permalink to &quot;生产环境挑战与调优&quot;">​</a></h4><ul><li>主要问题：单活跃 MDS 无法满足生产负载；元数据请求处理能力不足</li><li>调优措施：逐步增加活跃 MDS 数量至 7 个；将项目目录固定到特定 MDS；降低每个客户端能力数；增大缓存限制；调整缓存保留；优化修剪参数；调整删除操作；修改 MDS 故障转移超时</li></ul><h4 id="经验教训与改进方向" tabindex="-1">经验教训与改进方向 <a class="header-anchor" href="#经验教训与改进方向" aria-label="Permalink to &quot;经验教训与改进方向&quot;">​</a></h4><ul><li>应为复制池使用快速设备（减少小对象重平衡开销）</li><li>更仔细评估擦除编码算法（原使用 EC 2+2，后发现 ISA 算法在 AMD CPU 表现良好）</li><li>更早考虑多文件系统 (MultiFS) 方案</li></ul><h3 id="关键讨论点" tabindex="-1">关键讨论点 <a class="header-anchor" href="#关键讨论点" aria-label="Permalink to &quot;关键讨论点&quot;">​</a></h3><ol><li><strong>硬件配置经验</strong>：WAL+DB 使用单一快速设备 vs 分离设备；OSD 与 CPU 核心比例关系；CPU 绑定性能影响</li><li><strong>性能对比</strong>：CephFS 在小 IO 场景下性能仍不及 NFS；不建议将数据库工作负载直接放在 CephFS 上</li><li><strong>调度器选择</strong>：从 Queen 版本开始默认使用 mclock 调度器；部分用户报告在恢复操作时遇到问题，回退到 WPQ；更换调度器需要重启所有 OSD</li><li><strong>多文件系统 (MultiFS) 讨论</strong>：可用于隔离不同用户组/工作负载；数据迁移是主要挑战；自 Pacific 版本后被认为稳定</li><li><strong>元数据平衡</strong>：自动平衡器在繁忙目录上可能引发问题；手动固定大型活动目录树可能导致 MDS 过载</li></ol><h3 id="行动计划与后续工作" tabindex="-1">行动计划与后续工作 <a class="header-anchor" href="#行动计划与后续工作" aria-label="Permalink to &quot;行动计划与后续工作&quot;">​</a></h3><ol><li><strong>工具需求</strong>：开发比较 Ceph 不同版本默认配置差异的工具</li><li><strong>进一步测试</strong>：评估 ISA 擦除编码算法在 AMD CPU 上的表现；测试多文件系统 (MultiFS) 方案</li><li><strong>文档整理</strong>：分享 Matia 的演示材料；收集整理会议中提到的参考链接</li></ol><p>此次会议在技术细节交流和经验分享中圆满结束，与会者表示收获颇丰。下次会议将于两个月后举行。</p>',18)])])}const d=e(r,[["render",o]]);export{u as __pageData,d as default};
